    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$A conclusão fala da arte do desaparecimento, ser modelo dos fiéis não para ser amado ou reconhecido, mas para que Cristo apareça em nosso lugar e cresça enquanto diminuímos: onde, no seu coração, o desejo de ser notado ainda compete com o desejo de que Cristo seja visto através de você?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Jesus aponta para os lírios do campo, que crescem sem serem notados pelos homens e sob o cuidado diário de Deus, numa cultura em que todos querem seu lugar ao sol e ninguém aceita ser apenas mais um: o que dentro de você resiste a crescer no anonimato, sem aplauso, confiando que Deus mesmo cuida de você?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O texto encerra dizendo que o maior desafio do seguidor é crer que, apesar de sua quase invisibilidade pública, Cristo, também invisível, velará por ele: você consegue descansar nessa certeza de que Cristo nota o seu crescimento mesmo quando ninguém mais percebe, ou ainda mede o seu valor pelo reconhecimento dos outros?$p$, 'reflexao', null);
  end if;

end $migration$;
